insert into exercises (id, name_uk, name_en, primary_muscle_id, secondary_muscle_ids, equipment_type_id, required_equipment, mechanics, region, pattern, load_type, base_lift, base_ratio, difficulty, technique_uk, mistakes_uk) values
  ('barbell_back_squat', 'Присідання зі штангою на спині', 'Barbell back squat', 'quads', array['glutes', 'adductors', 'lower_back']::text[], 'barbell', array['barbell', 'barbell_rack']::text[], 'compound', 'lower', 'squat', 'barbell', 'squat', 1, 2, 'Гриф на трапеціях, стопи на ширині плечей, носки трохи врозтіч. Вдихни, напруж прес і опускайся, ведучи таз назад і коліна в напрямку носків, до паралелі стегна з підлогою або нижче. Вставай, тиснучи всією стопою.', array['Коліна заходять всередину', 'Спина округлюється внизу', 'Відрив п''ят від підлоги']::text[]),
  ('barbell_front_squat', 'Фронтальні присідання', 'Front squat', 'quads', array['glutes', 'abs']::text[], 'barbell', array['barbell', 'barbell_rack']::text[], 'compound', 'lower', 'squat', 'barbell', 'squat', 0.8, 3, 'Гриф на передніх дельтах, лікті високо. Корпус максимально вертикальний, опускайся глибоко між колінами і вставай, не опускаючи лікті.', array['Лікті падають, гриф скочується', 'Завал корпусу вперед']::text[]),
  ('goblet_squat', 'Гоблет-присідання з гантеллю', 'Goblet squat', 'quads', array['glutes']::text[], 'dumbbell', array['dumbbells']::text[], 'compound', 'lower', 'squat', 'dumbbell', 'squat', 0.3, 1, 'Тримай гантель вертикально біля грудей. Присідай глибоко, лікті проходять між колінами, спина рівна.', array['Гантель відходить від грудей', 'Неповна амплітуда']::text[]),
  ('smith_squat', 'Присідання в тренажері Смітта', 'Smith machine squat', 'quads', array['glutes']::text[], 'smith', array['smith']::text[], 'compound', 'lower', 'squat', 'barbell', 'squat', 0.85, 1, 'Стопи трохи попереду грифа. Опускайся контрольовано до паралелі, тисни п''ятами й серединою стопи.', array['Стопи прямо під грифом — навантаження на коліна', 'Різкий відбив унизу']::text[]),
  ('hack_squat', 'Гакк-присідання', 'Hack squat', 'quads', array['glutes']::text[], 'machine', array['hack_squat']::text[], 'compound', 'lower', 'squat', 'machine', 'squat', 1.1, 1, 'Спина й таз щільно притиснуті до спинки. Опускайся якомога глибше без відриву таза, вставай, не випрямляючи коліна до клацання.', array['Таз відривається від спинки', 'Повне блокування колін угорі']::text[]),
  ('leg_press_45', 'Жим ногами 45°', 'Leg press 45°', 'quads', array['glutes', 'hamstrings']::text[], 'machine', array['leg_press_45']::text[], 'compound', 'lower', 'squat', 'machine', 'squat', 1.8, 1, 'Стопи на середині платформи на ширині плечей. Опускай платформу, доки таз не почне відриватися від сидіння, потім вижимай, не блокуючи колін.', array['Таз підкручується й відривається', 'Різке блокування колін', 'Коліна сходяться']::text[]),
  ('leg_press_horizontal', 'Горизонтальний жим ногами', 'Seated leg press', 'quads', array['glutes']::text[], 'machine', array['leg_press_horizontal']::text[], 'compound', 'lower', 'squat', 'machine', 'squat', 1.2, 1, 'Сядь щільно, стопи на ширині плечей. Згинай ноги до кута приблизно 90° і плавно випрямляй.', array['Неповна амплітуда', 'Відрив таза від сидіння']::text[]),
  ('bodyweight_squat', 'Присідання з власною вагою', 'Bodyweight squat', 'quads', array['glutes']::text[], 'bodyweight', '{}'::text[], 'compound', 'lower', 'squat', 'bodyweight', null, null, 1, 'Стопи на ширині плечей, руки перед собою. Присідай до паралелі, тримаючи спину рівною й п''яти на підлозі.', array['Коліна всередину', 'П''яти відриваються']::text[]),
  ('bulgarian_split_squat', 'Болгарські випади', 'Bulgarian split squat', 'quads', array['glutes', 'adductors']::text[], 'dumbbell', array['dumbbells', 'flat_bench']::text[], 'compound', 'lower', 'lunge', 'dumbbell', 'squat', 0.2, 2, 'Задня нога на лаві, передня — на крок попереду. Опускайся вертикально вниз, доки стегно передньої ноги не стане паралельним підлозі.', array['Занадто короткий крок', 'Коліно передньої ноги завалюється всередину']::text[]),
  ('walking_lunge', 'Випади з гантелями', 'Dumbbell lunges', 'quads', array['glutes']::text[], 'dumbbell', array['dumbbells']::text[], 'compound', 'lower', 'lunge', 'dumbbell', 'squat', 0.22, 1, 'Гантелі в опущених руках. Зроби широкий крок, опустись до майже торкання коліном підлоги, відштовхнись передньою ногою.', array['Удар коліном об підлогу', 'Корпус нахиляється вперед']::text[]),
  ('reverse_lunge_bw', 'Зворотні випади', 'Reverse lunges', 'quads', array['glutes']::text[], 'bodyweight', '{}'::text[], 'compound', 'lower', 'lunge', 'bodyweight', null, null, 1, 'Крокуй назад і опускайся, доки обидва коліна не зігнуться приблизно під 90°. Повертайся, тиснучи п''ятою передньої ноги.', array['Втрата балансу через вузьку постановку', 'Неповна амплітуда']::text[]),
  ('step_up', 'Зашагування на лаву', 'Step-ups', 'quads', array['glutes']::text[], 'dumbbell', array['dumbbells', 'flat_bench']::text[], 'compound', 'lower', 'lunge', 'dumbbell', 'squat', 0.2, 1, 'Постав всю стопу на лаву і підіймайся силою цієї ноги, не відштовхуючись нижньою.', array['Поштовх нижньою ногою', 'Коліно завалюється всередину']::text[]),
  ('barbell_deadlift', 'Станова тяга', 'Deadlift', 'glutes', array['hamstrings', 'lower_back', 'upper_back', 'forearms']::text[], 'barbell', array['barbell']::text[], 'compound', 'lower', 'hinge', 'barbell', 'deadlift', 1, 2, 'Гриф над серединою стопи, хват трохи ширше ніг. Опусти таз, випрями спину, вдихни й напруж прес. Тягни гриф уздовж ніг, одночасно розгинаючи коліна й таз.', array['Округлена спина', 'Гриф відходить від ніг', 'Ривок замість плавного старту']::text[]),
  ('romanian_deadlift', 'Румунська тяга', 'Romanian deadlift', 'hamstrings', array['glutes', 'lower_back']::text[], 'barbell', array['barbell']::text[], 'compound', 'lower', 'hinge', 'barbell', 'deadlift', 0.6, 2, 'Ноги злегка зігнуті й майже нерухомі. Відводь таз назад, ковзаючи грифом по стегнах, доки не відчуєш сильне розтягнення задньої поверхні стегна.', array['Округлення спини внизу', 'Присідання замість нахилу']::text[]),
  ('dumbbell_rdl', 'Румунська тяга з гантелями', 'Dumbbell Romanian deadlift', 'hamstrings', array['glutes']::text[], 'dumbbell', array['dumbbells']::text[], 'compound', 'lower', 'hinge', 'dumbbell', 'deadlift', 0.25, 1, 'Гантелі перед стегнами. Відводь таз назад зі злегка зігнутими колінами, тримай гантелі близько до ніг, спина рівна.', array['Гантелі далеко від ніг', 'Округлена спина']::text[]),
  ('sumo_deadlift', 'Станова тяга сумо', 'Sumo deadlift', 'glutes', array['adductors', 'quads', 'hamstrings']::text[], 'barbell', array['barbell']::text[], 'compound', 'lower', 'hinge', 'barbell', 'deadlift', 0.95, 3, 'Широка постановка, носки врозтіч, хват між ногами. Розводь коліна в сторони, тримай груди високо й тягни гриф вертикально вгору.', array['Коліна сходяться', 'Таз піднімається раніше за плечі']::text[]),
  ('kettlebell_swing', 'Махи гирею', 'Kettlebell swing', 'glutes', array['hamstrings', 'lower_back']::text[], 'kettlebell', array['kettlebells']::text[], 'compound', 'lower', 'hinge', 'kettlebell', 'deadlift', 0.15, 2, 'Рух іде від таза: відведи гирю між ніг і різко розігни таз, щоб вона піднялась до рівня грудей. Руки лише тримають.', array['Підйом гирі руками', 'Присідання замість нахилу']::text[]),
  ('hip_thrust', 'Сідничний міст зі штангою', 'Barbell hip thrust', 'glutes', array['hamstrings']::text[], 'barbell', array['barbell', 'flat_bench']::text[], 'compound', 'lower', 'hip_ext', 'barbell', 'deadlift', 0.7, 1, 'Лопатки на лаві, гриф на тазу (з м''якою накладкою). Підіймай таз до прямої лінії від колін до плечей і затримайся на секунду, стискаючи сідниці.', array['Прогин у попереку вгорі', 'Стопи надто далеко — працює біцепс стегна']::text[]),
  ('glute_bridge_machine', 'Сідничний міст у тренажері', 'Hip thrust machine', 'glutes', array['hamstrings']::text[], 'machine', array['glute_bridge_machine']::text[], 'compound', 'lower', 'hip_ext', 'machine', 'deadlift', 0.6, 1, 'Займи положення за інструкцією тренажера. Підіймай таз до повного розгинання, затримайся вгорі.', array['Прогин у попереку', 'Неповне розгинання таза']::text[]),
  ('glute_kickback_cable', 'Відведення ноги назад у кросовері', 'Cable glute kickback', 'glutes', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'lower', 'hip_ext', 'cable', null, null, 1, 'Манжета на щиколотці, легкий нахил вперед. Відводь пряму ногу назад за рахунок сідниць, без прогину в попереку.', array['Прогин у попереку', 'Розгойдування корпусу']::text[]),
  ('glute_kickback_machine', 'Відведення ноги назад у тренажері', 'Glute kickback machine', 'glutes', '{}'::text[], 'machine', array['glute_kickback_machine']::text[], 'isolation', 'lower', 'hip_ext', 'machine', null, null, 1, 'Упрись у тренажер за інструкцією. Відштовхуй платформу ногою назад, стискаючи сідницю вгорі.', array['Рух за рахунок попереку', 'Занадто велика вага й ривки']::text[]),
  ('hyperextension', 'Гіперекстензія', 'Back extension', 'lower_back', array['glutes', 'hamstrings']::text[], 'bodyweight', array['hyperextension_bench']::text[], 'compound', 'lower', 'hinge', 'bodyweight', null, null, 1, 'Валик під тазом. Опускайся з рівною спиною і піднімайся до прямої лінії тіла, без переразгинання.', array['Переразгинання вгорі', 'Ривки']::text[]),
  ('leg_extension', 'Розгинання ніг у тренажері', 'Leg extension', 'quads', '{}'::text[], 'machine', array['leg_extension']::text[], 'isolation', 'lower', 'knee_ext', 'machine', 'squat', 0.35, 1, 'Вісь тренажера на рівні колін, валик над щиколотками. Випрямляй ноги до кінця, на секунду затримайся і повільно опускай.', array['Ривки й відрив таза', 'Швидке опускання']::text[]),
  ('lying_leg_curl', 'Згинання ніг лежачи', 'Lying leg curl', 'hamstrings', array['calves']::text[], 'machine', array['leg_curl_lying']::text[], 'isolation', 'lower', 'knee_flex', 'machine', 'deadlift', 0.2, 1, 'Колінa трохи за краєм лави, валик над п''ятами. Згинай ноги, не відриваючи таз, і плавно опускай.', array['Таз піднімається', 'Неповна амплітуда']::text[]),
  ('seated_leg_curl', 'Згинання ніг сидячи', 'Seated leg curl', 'hamstrings', '{}'::text[], 'machine', array['leg_curl_seated']::text[], 'isolation', 'lower', 'knee_flex', 'machine', 'deadlift', 0.25, 1, 'Зафіксуй стегна упором. Згинай ноги максимально, контролюй повернення.', array['Вісь тренажера не на рівні колін', 'Ривки']::text[]),
  ('standing_calf_raise', 'Підйоми на носки стоячи', 'Standing calf raise', 'calves', '{}'::text[], 'machine', array['calf_raise_standing']::text[], 'isolation', 'lower', 'calf', 'machine', 'squat', 0.6, 1, 'Носки на краю платформи. Опускай п''яти максимально вниз із розтягненням, потім підіймайся якомога вище, затримка 1 с.', array['Пружинні короткі рухи', 'Згинання колін']::text[]),
  ('seated_calf_raise', 'Підйоми на носки сидячи', 'Seated calf raise', 'calves', '{}'::text[], 'machine', array['calf_raise_seated']::text[], 'isolation', 'lower', 'calf', 'machine', 'squat', 0.35, 1, 'Валик на стегнах біля колін. Повна амплітуда з паузою внизу й угорі.', array['Неповна амплітуда', 'Занадто швидкий темп']::text[]),
  ('calf_raise_bw', 'Підйоми на носки з власною вагою', 'Bodyweight calf raise', 'calves', '{}'::text[], 'bodyweight', '{}'::text[], 'isolation', 'lower', 'calf', 'bodyweight', null, null, 1, 'Стань носками на сходинку, тримайся за опору. Повільно опускайся й підіймайся з паузою вгорі.', array['Швидкі пружинні рухи']::text[]),
  ('leg_press_calf', 'Підйоми на носки в жимі ногами', 'Leg press calf raise', 'calves', '{}'::text[], 'machine', array['leg_press_45']::text[], 'isolation', 'lower', 'calf', 'machine', 'squat', 0.9, 1, 'Носки на нижньому краї платформи, ноги майже прямі. Тисни платформу носками з повною амплітудою.', array['Згинання колін', 'Зісковзування стоп']::text[]),
  ('hip_abduction', 'Розведення ніг у тренажері', 'Hip abduction', 'abductors', array['glutes']::text[], 'machine', array['hip_abduction']::text[], 'isolation', 'lower', 'hip_abd', 'machine', null, null, 1, 'Сядь щільно, розводь ноги в сторони плавно й контрольовано повертай.', array['Удар вагою в кінці руху', 'Розгойдування корпусу']::text[]),
  ('hip_adduction', 'Зведення ніг у тренажері', 'Hip adduction', 'adductors', '{}'::text[], 'machine', array['hip_adduction']::text[], 'isolation', 'lower', 'hip_add', 'machine', null, null, 1, 'Зводь ноги, долаючи опір, і повільно розводь до комфортного розтягнення.', array['Надто широке розведення з болем', 'Ривки']::text[]),
  ('barbell_bench_press', 'Жим штанги лежачи', 'Barbell bench press', 'chest', array['front_delts', 'triceps']::text[], 'barbell', array['barbell', 'flat_bench']::text[], 'compound', 'upper', 'h_push', 'barbell', 'bench', 1, 2, 'Лопатки зведені й опущені, стопи на підлозі. Опускай гриф на низ грудей, лікті під кутом близько 45° до тулуба, і вижимай угору.', array['Відбив грифа від грудей', 'Лікті розведені під 90°', 'Відрив таза від лави']::text[]),
  ('incline_barbell_press', 'Жим штанги на похилій лаві', 'Incline barbell press', 'chest', array['front_delts', 'triceps']::text[], 'barbell', array['barbell', 'adjustable_bench']::text[], 'compound', 'upper', 'h_push', 'barbell', 'bench', 0.8, 2, 'Нахил лави 30°. Опускай гриф на верх грудей і вижимай вертикально.', array['Надто великий нахил — працюють плечі', 'Відрив лопаток']::text[]),
  ('dumbbell_bench_press', 'Жим гантелей лежачи', 'Dumbbell bench press', 'chest', array['front_delts', 'triceps']::text[], 'dumbbell', array['dumbbells', 'flat_bench']::text[], 'compound', 'upper', 'h_push', 'dumbbell', 'bench', 0.38, 1, 'Лопатки зведені, гантелі над грудьми. Опускай до легкого розтягнення грудей і вижимай, трохи зводячи гантелі вгорі.', array['Гантелі стукаються вгорі', 'Лікті надто широко']::text[]),
  ('incline_dumbbell_press', 'Жим гантелей на похилій лаві', 'Incline dumbbell press', 'chest', array['front_delts', 'triceps']::text[], 'dumbbell', array['dumbbells', 'adjustable_bench']::text[], 'compound', 'upper', 'h_push', 'dumbbell', 'bench', 0.32, 1, 'Лава під 30°, лопатки зведені. Опускай гантелі до рівня грудей і вижимай угору.', array['Кут лави понад 45°', 'Неповна амплітуда']::text[]),
  ('smith_incline_press', 'Жим на похилій лаві в Сміті', 'Smith incline press', 'chest', array['front_delts', 'triceps']::text[], 'smith', array['smith', 'adjustable_bench']::text[], 'compound', 'upper', 'h_push', 'barbell', 'bench', 0.75, 1, 'Постав лаву так, щоб гриф опускався на верх грудей. Контрольовано опускай і вижимай.', array['Гриф опускається на шию або живіт', 'Відрив лопаток']::text[]),
  ('chest_press_machine', 'Жим від грудей у тренажері', 'Chest press machine', 'chest', array['front_delts', 'triceps']::text[], 'machine', array['chest_press_machine']::text[], 'compound', 'upper', 'h_push', 'machine', 'bench', 0.8, 1, 'Ручки на рівні середини грудей, лопатки притиснуті до спинки. Вижимай, не блокуючи лікті.', array['Сидіння надто високо або низько', 'Плечі піднімаються до вух']::text[]),
  ('incline_lever_press', 'Жим під кутом у важільному тренажері', 'Incline lever press', 'chest', array['front_delts', 'triceps']::text[], 'machine', array['incline_press_lever']::text[], 'compound', 'upper', 'h_push', 'machine', 'bench', 0.7, 1, 'Притисни лопатки до спинки, вижимай ручки вгору-вперед і плавно повертай.', array['Неповна амплітуда', 'Відрив спини']::text[]),
  ('push_up', 'Віджимання від підлоги', 'Push-ups', 'chest', array['triceps', 'front_delts', 'abs']::text[], 'bodyweight', '{}'::text[], 'compound', 'upper', 'h_push', 'bodyweight', null, null, 1, 'Руки трохи ширше плечей, тіло пряме від голови до п''ят. Опускайся грудьми майже до підлоги, лікті під 45°.', array['Провисання таза', 'Неповна амплітуда']::text[]),
  ('dips', 'Віджимання на брусах', 'Dips', 'chest', array['triceps', 'front_delts']::text[], 'bodyweight', array['dip_bars']::text[], 'compound', 'upper', 'h_push', 'bodyweight', null, null, 2, 'Легкий нахил вперед, опускайся до кута в ліктях близько 90° і вижимай угору.', array['Надто глибоке опускання з болем у плечах', 'Розгойдування']::text[]),
  ('cable_fly', 'Зведення рук у кросовері', 'Cable fly', 'chest', array['front_delts']::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'chest_iso', 'cable', null, null, 1, 'Крок уперед, руки злегка зігнуті. Зводь ручки дугою перед грудьми, стискаючи груди, і плавно розводь.', array['Згинання ліктів — рух стає жимом', 'Розгойдування корпусу']::text[]),
  ('pec_deck', 'Зведення рук у пек-деку', 'Pec deck', 'chest', array['front_delts']::text[], 'machine', array['pec_deck']::text[], 'isolation', 'upper', 'chest_iso', 'machine', 'bench', 0.45, 1, 'Ручки на рівні грудей, лопатки притиснуті. Зводь руки до торкання, плавно повертай до розтягнення.', array['Сидіння надто низько', 'Ривки на старті']::text[]),
  ('dumbbell_fly', 'Розведення гантелей лежачи', 'Dumbbell fly', 'chest', '{}'::text[], 'dumbbell', array['dumbbells', 'flat_bench']::text[], 'isolation', 'upper', 'chest_iso', 'dumbbell', 'bench', 0.15, 2, 'Руки злегка зігнуті й фіксовані. Розводь гантелі дугою до розтягнення грудей і зводь угорі.', array['Занадто велика вага й глибоке опускання', 'Згинання ліктів']::text[]),
  ('pull_up', 'Підтягування', 'Pull-ups', 'lats', array['biceps', 'upper_back']::text[], 'bodyweight', array['pullup_bar']::text[], 'compound', 'upper', 'v_pull', 'bodyweight', 'pullup', 1, 2, 'Хват трохи ширше плечей. Тягнися грудьми до перекладини, зводячи лопатки, і повністю опускайся.', array['Розгойдування й ривки', 'Неповне опускання']::text[]),
  ('chin_up', 'Підтягування зворотним хватом', 'Chin-ups', 'lats', array['biceps']::text[], 'bodyweight', array['pullup_bar']::text[], 'compound', 'upper', 'v_pull', 'bodyweight', 'pullup', 1, 2, 'Хват долонями до себе на ширині плечей. Підтягуйся до підборіддя над перекладиною.', array['Тягнешся підборіддям, а не грудьми', 'Ривки']::text[]),
  ('assisted_pullup', 'Підтягування в гравітроні', 'Assisted pull-ups', 'lats', array['biceps', 'upper_back']::text[], 'machine', array['assisted_pullup']::text[], 'compound', 'upper', 'v_pull', 'assisted', null, null, 1, 'Встань колінами на платформу. Що більша вага противаги, то легше. Тягнися грудьми до ручок і повністю опускайся.', array['Надто велика допомога — немає прогресу', 'Неповна амплітуда']::text[]),
  ('lat_pulldown', 'Тяга верхнього блока', 'Lat pulldown', 'lats', array['biceps', 'upper_back']::text[], 'cable', array['lat_pulldown']::text[], 'compound', 'upper', 'v_pull', 'cable', 'row', 0.85, 1, 'Хват ширше плечей, легкий нахил назад. Тягни руків''я до верху грудей ліктями вниз, плавно повертай.', array['Тяга за голову', 'Сильне відхилення корпусу назад']::text[]),
  ('lat_pulldown_close', 'Тяга верхнього блока вузьким хватом', 'Close-grip pulldown', 'lats', array['biceps']::text[], 'cable', array['lat_pulldown']::text[], 'compound', 'upper', 'v_pull', 'cable', 'row', 0.8, 1, 'V-подібна ручка, тягни до верху грудей, лікті вздовж тулуба.', array['Рух лише руками', 'Ривки корпусом']::text[]),
  ('lever_pulldown', 'Тяга зверху у важільному тренажері', 'Lever pulldown', 'lats', array['biceps']::text[], 'machine', array['pulldown_lever']::text[], 'compound', 'upper', 'v_pull', 'machine', 'row', 0.8, 1, 'Зафіксуй стегна, тягни ручки вниз, зводячи лопатки.', array['Неповна амплітуда', 'Підйом плечей']::text[]),
  ('barbell_bent_over_row', 'Тяга штанги в нахилі', 'Barbell row', 'upper_back', array['lats', 'biceps', 'lower_back']::text[], 'barbell', array['barbell']::text[], 'compound', 'upper', 'h_pull', 'barbell', 'row', 1, 2, 'Нахил корпусу 30–45°, спина рівна. Тягни гриф до низу живота, зводячи лопатки.', array['Округлена спина', 'Корпус піднімається з кожним повтором']::text[]),
  ('dumbbell_row', 'Тяга гантелі однією рукою', 'One-arm dumbbell row', 'lats', array['upper_back', 'biceps']::text[], 'dumbbell', array['dumbbells', 'flat_bench']::text[], 'compound', 'upper', 'h_pull', 'dumbbell', 'row', 0.45, 1, 'Коліно й рука на лаві, спина паралельна підлозі. Тягни гантель до пояса ліктем назад.', array['Скручування корпусу', 'Тяга до грудей замість пояса']::text[]),
  ('seated_cable_row', 'Тяга нижнього блока', 'Seated cable row', 'upper_back', array['lats', 'biceps']::text[], 'cable', array['seated_cable_row']::text[], 'compound', 'upper', 'h_pull', 'cable', 'row', 0.9, 1, 'Спина рівна, легкий згин колін. Тягни руків''я до живота, зводячи лопатки, без розгойдування.', array['Розгойдування корпусом', 'Округлення спини на поверненні']::text[]),
  ('t_bar_row', 'Тяга Т-грифа', 'T-bar row', 'upper_back', array['lats', 'biceps']::text[], 'barbell', array['t_bar_row']::text[], 'compound', 'upper', 'h_pull', 'machine', 'row', 0.8, 2, 'Нахил корпусу, спина рівна. Тягни гриф до низу грудей, контролюй опускання.', array['Округлена спина', 'Ривки корпусом']::text[]),
  ('lever_row', 'Тяга у важільному тренажері', 'Lever row', 'upper_back', array['lats', 'biceps']::text[], 'machine', array['row_machine']::text[], 'compound', 'upper', 'h_pull', 'machine', 'row', 0.85, 1, 'Груди на упорі. Тягни ручки до себе, зводячи лопатки, і плавно повертай.', array['Відрив грудей від упору', 'Неповна амплітуда']::text[]),
  ('inverted_row', 'Австралійські підтягування', 'Inverted row', 'upper_back', array['lats', 'biceps']::text[], 'bodyweight', array['barbell_rack']::text[], 'compound', 'upper', 'h_pull', 'bodyweight', null, null, 1, 'Гриф на рівні пояса, тіло пряме під ним. Тягнися грудьми до грифа, зводячи лопатки.', array['Провисання таза', 'Неповна амплітуда']::text[]),
  ('straight_arm_pulldown', 'Пуловер у кросовері прямими руками', 'Straight-arm pulldown', 'lats', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'lat_iso', 'cable', null, null, 1, 'Руки майже прямі, легкий нахил вперед. Опускай руків''я дугою до стегон силою найширших.', array['Згинання ліктів', 'Розгойдування']::text[]),
  ('barbell_shrug', 'Шраги зі штангою', 'Barbell shrug', 'traps', '{}'::text[], 'barbell', array['barbell']::text[], 'isolation', 'upper', 'traps', 'barbell', 'deadlift', 0.5, 1, 'Піднімай плечі прямо вгору до вух, затримайся й опускай. Без обертання плечима.', array['Обертання плечима', 'Згинання рук']::text[]),
  ('dumbbell_shrug', 'Шраги з гантелями', 'Dumbbell shrug', 'traps', '{}'::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'traps', 'dumbbell', 'deadlift', 0.25, 1, 'Гантелі вздовж тулуба. Піднімай плечі вгору, пауза, повільно опускай.', array['Коротка амплітуда']::text[]),
  ('face_pull', 'Тяга канату до обличчя', 'Face pull', 'rear_delts', array['upper_back']::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'rear_delt', 'cable', null, null, 1, 'Блок на рівні обличчя. Тягни канат до лоба, розводячи кінці й лікті в сторони.', array['Занадто велика вага — рух корпусом', 'Лікті опущені']::text[]),
  ('reverse_pec_deck', 'Зворотні розведення в пек-деку', 'Reverse pec deck', 'rear_delts', array['upper_back']::text[], 'machine', array['pec_deck']::text[], 'isolation', 'upper', 'rear_delt', 'machine', null, null, 1, 'Груди до спинки, руки злегка зігнуті. Розводь руки назад силою задніх дельт.', array['Зведення лопаток замість роботи дельт', 'Ривки']::text[]),
  ('rear_delt_dumbbell_fly', 'Розведення гантелей у нахилі', 'Bent-over reverse fly', 'rear_delts', array['upper_back']::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'rear_delt', 'dumbbell', null, null, 1, 'Нахил майже паралельно підлозі. Розводь гантелі в сторони, лікті злегка зігнуті.', array['Підйом корпусу', 'Важкі гантелі й інерція']::text[]),
  ('barbell_overhead_press', 'Жим штанги стоячи', 'Overhead press', 'front_delts', array['side_delts', 'triceps']::text[], 'barbell', array['barbell', 'barbell_rack']::text[], 'compound', 'upper', 'v_push', 'barbell', 'ohp', 1, 2, 'Гриф на передніх дельтах, сідниці й прес напружені. Вижимай гриф вертикально, проводячи голову вперед під нього.', array['Прогин у попереку', 'Гриф іде дугою вперед']::text[]),
  ('seated_dumbbell_press', 'Жим гантелей сидячи', 'Seated dumbbell press', 'front_delts', array['side_delts', 'triceps']::text[], 'dumbbell', array['dumbbells', 'adjustable_bench']::text[], 'compound', 'upper', 'v_push', 'dumbbell', 'ohp', 0.4, 1, 'Спинка майже вертикальна. Вижимай гантелі вгору від рівня вух, не стукаючи ними.', array['Прогин у попереку', 'Неповна амплітуда']::text[]),
  ('shoulder_press_machine', 'Жим угору в тренажері', 'Shoulder press machine', 'front_delts', array['side_delts', 'triceps']::text[], 'machine', array['shoulder_press_machine']::text[], 'compound', 'upper', 'v_push', 'machine', 'ohp', 0.9, 1, 'Ручки на рівні плечей. Вижимай угору без блокування ліктів і контролюй опускання.', array['Сидіння надто високо', 'Відрив спини']::text[]),
  ('smith_overhead_press', 'Жим сидячи в Сміті', 'Smith overhead press', 'front_delts', array['side_delts', 'triceps']::text[], 'smith', array['smith', 'adjustable_bench']::text[], 'compound', 'upper', 'v_push', 'barbell', 'ohp', 0.9, 1, 'Лава під гриф так, щоб він опускався перед обличчям до підборіддя. Вижимай угору.', array['Гриф опускається на голову', 'Прогин у попереку']::text[]),
  ('arnold_press', 'Жим Арнольда', 'Arnold press', 'front_delts', array['side_delts', 'triceps']::text[], 'dumbbell', array['dumbbells', 'adjustable_bench']::text[], 'compound', 'upper', 'v_push', 'dumbbell', 'ohp', 0.35, 2, 'Старт: гантелі перед обличчям, долоні до себе. Вижимаючи, розвертай долоні вперед.', array['Поспіх і втрата контролю']::text[]),
  ('pike_push_up', 'Віджимання «щука»', 'Pike push-ups', 'front_delts', array['triceps']::text[], 'bodyweight', '{}'::text[], 'compound', 'upper', 'v_push', 'bodyweight', null, null, 2, 'Таз високо, тіло у формі перевернутої V. Опускай голову до підлоги між руками й вижимай.', array['Таз опускається — виходять звичайні віджимання']::text[]),
  ('lateral_raise', 'Махи гантелями в сторони', 'Lateral raise', 'side_delts', '{}'::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'side_delt', 'dumbbell', 'ohp', 0.15, 1, 'Легкий нахил вперед, лікті злегка зігнуті. Піднімай гантелі в сторони до рівня плечей, ведучи ліктями.', array['Розгойдування корпусом', 'Підйом плечей до вух']::text[]),
  ('cable_lateral_raise', 'Махи в сторони в кросовері', 'Cable lateral raise', 'side_delts', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'side_delt', 'cable', null, null, 1, 'Нижній блок, рука з протилежного боку. Піднімай руку в сторону до рівня плеча.', array['Ривки', 'Згинання ліктя']::text[]),
  ('lateral_raise_machine', 'Махи в сторони в тренажері', 'Lateral raise machine', 'side_delts', '{}'::text[], 'machine', array['lateral_raise_machine']::text[], 'isolation', 'upper', 'side_delt', 'machine', null, null, 1, 'Вісь тренажера на рівні плечей. Піднімай руки в сторони і плавно опускай.', array['Підйом плечей', 'Ривки']::text[]),
  ('barbell_curl', 'Згинання рук зі штангою', 'Barbell curl', 'biceps', array['forearms']::text[], 'barbell', array['barbell']::text[], 'isolation', 'upper', 'biceps', 'barbell', 'row', 0.4, 1, 'Лікті притиснуті до тулуба. Згинай руки без розгойдування й повільно опускай.', array['Розгойдування корпусом', 'Лікті йдуть вперед']::text[]),
  ('ez_curl', 'Згинання рук з EZ-грифом', 'EZ-bar curl', 'biceps', array['forearms']::text[], 'ez_bar', array['ez_bar']::text[], 'isolation', 'upper', 'biceps', 'barbell', 'row', 0.38, 1, 'Хват за вигини грифа, лікті нерухомі. Повна амплітуда без інерції.', array['Неповне розгинання внизу', 'Інерція']::text[]),
  ('dumbbell_curl', 'Згинання рук з гантелями', 'Dumbbell curl', 'biceps', array['forearms']::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'biceps', 'dumbbell', 'row', 0.17, 1, 'Згинай руки по черзі або разом, розвертаючи долоні вгору. Лікті на місці.', array['Розгойдування', 'Швидке опускання']::text[]),
  ('hammer_curl', 'Молотки', 'Hammer curl', 'biceps', array['forearms']::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'biceps', 'dumbbell', 'row', 0.18, 1, 'Нейтральний хват (долоні одна до одної). Згинай руки, не розгойдуючи корпус.', array['Лікті відходять від тулуба']::text[]),
  ('preacher_curl', 'Згинання на лаві Скотта', 'Preacher curl', 'biceps', '{}'::text[], 'ez_bar', array['ez_bar', 'preacher_bench']::text[], 'isolation', 'upper', 'biceps', 'barbell', 'row', 0.3, 1, 'Плечі щільно на подушці. Опускай гриф майже до повного випрямлення і згинай.', array['Різке повне розгинання з вагою', 'Відрив ліктів']::text[]),
  ('cable_curl', 'Згинання рук на нижньому блоці', 'Cable curl', 'biceps', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'biceps', 'cable', null, null, 1, 'Прямий або EZ-руків''я на нижньому блоці. Лікті притиснуті, рух лише в ліктьовому суглобі.', array['Нахил корпусу назад']::text[]),
  ('biceps_machine', 'Згинання рук у тренажері', 'Biceps curl machine', 'biceps', '{}'::text[], 'machine', array['biceps_curl_machine']::text[], 'isolation', 'upper', 'biceps', 'machine', null, null, 1, 'Лікті на осі тренажера. Згинай руки повністю, контролюй опускання.', array['Лікті не на осі', 'Ривки']::text[]),
  ('triceps_pushdown', 'Розгинання рук на блоці', 'Triceps pushdown', 'triceps', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'upper', 'triceps', 'cable', null, null, 1, 'Лікті притиснуті до тулуба. Розгинай руки донизу до кінця, повертай до кута 90°.', array['Лікті рухаються', 'Нахил і тиск вагою тіла']::text[]),
  ('skull_crusher', 'Французький жим лежачи', 'Skull crusher', 'triceps', '{}'::text[], 'ez_bar', array['ez_bar', 'flat_bench']::text[], 'isolation', 'upper', 'triceps', 'barbell', 'bench', 0.3, 2, 'Плечі нерухомі під невеликим кутом за голову. Згинай лише лікті, опускаючи гриф до лоба або за голову.', array['Лікті розходяться', 'Рух плечима']::text[]),
  ('overhead_dumbbell_extension', 'Розгинання гантелі з-за голови', 'Overhead dumbbell extension', 'triceps', '{}'::text[], 'dumbbell', array['dumbbells']::text[], 'isolation', 'upper', 'triceps', 'dumbbell', 'bench', 0.2, 1, 'Гантель двома руками за головою, лікті дивляться вгору. Розгинай руки вертикально.', array['Лікті розводяться', 'Прогин у попереку']::text[]),
  ('close_grip_bench', 'Жим лежачи вузьким хватом', 'Close-grip bench press', 'triceps', array['chest', 'front_delts']::text[], 'barbell', array['barbell', 'flat_bench']::text[], 'compound', 'upper', 'triceps', 'barbell', 'bench', 0.85, 2, 'Хват на ширині плечей. Опускай гриф на низ грудей, лікті вздовж тулуба.', array['Надто вузький хват — біль у зап''ястях', 'Лікті розведені']::text[]),
  ('triceps_machine', 'Розгинання рук у тренажері', 'Triceps machine', 'triceps', '{}'::text[], 'machine', array['triceps_machine']::text[], 'isolation', 'upper', 'triceps', 'machine', null, null, 1, 'Лікті на осі тренажера. Розгинай руки повністю, плавно повертай.', array['Відрив ліктів від подушки']::text[]),
  ('bench_dip', 'Зворотні віджимання від лави', 'Bench dips', 'triceps', array['front_delts']::text[], 'bodyweight', array['flat_bench']::text[], 'isolation', 'upper', 'triceps', 'bodyweight', null, null, 1, 'Руки на краю лави за спиною. Опускайся до кута в ліктях 90° і вижимай.', array['Надто глибоке опускання — навантаження на плечі']::text[]),
  ('plank', 'Планка', 'Plank', 'abs', array['obliques']::text[], 'bodyweight', '{}'::text[], 'isolation', 'core', 'core', 'timed', null, null, 1, 'Упор на передпліччя, тіло пряме від голови до п''ят. Напруж прес і сідниці, дихай рівно.', array['Провисання або підйом таза', 'Затримка дихання']::text[]),
  ('side_plank', 'Бічна планка', 'Side plank', 'obliques', array['abs']::text[], 'bodyweight', '{}'::text[], 'isolation', 'core', 'core', 'timed', null, null, 1, 'Упор на передпліччя збоку, тіло пряме. Тримай таз високо.', array['Таз провисає']::text[]),
  ('hanging_leg_raise', 'Підйом ніг у висі', 'Hanging leg raise', 'abs', array['obliques']::text[], 'bodyweight', array['pullup_bar']::text[], 'isolation', 'core', 'core', 'bodyweight', null, null, 2, 'Вис на турніку. Піднімай ноги, підкручуючи таз, без розгойдування.', array['Розгойдування', 'Рух лише стегнами без підкручування таза']::text[]),
  ('roman_chair_leg_raise', 'Підйом ніг на брусах', 'Captain''s chair leg raise', 'abs', '{}'::text[], 'bodyweight', array['dip_bars']::text[], 'isolation', 'core', 'core', 'bodyweight', null, null, 1, 'Упор на передпліччя, спина притиснута. Піднімай коліна до грудей.', array['Ривки', 'Прогин спини']::text[]),
  ('cable_crunch', 'Скручування на блоці', 'Cable crunch', 'abs', '{}'::text[], 'cable', array['cable_crossover']::text[], 'isolation', 'core', 'core', 'cable', null, null, 1, 'На колінах, канат біля голови. Скручуйся, наближаючи лікті до колін силою преса.', array['Рух тазом замість скручування']::text[]),
  ('ab_crunch_machine', 'Скручування в тренажері', 'Ab crunch machine', 'abs', '{}'::text[], 'machine', array['ab_crunch_machine']::text[], 'isolation', 'core', 'core', 'machine', null, null, 1, 'Скручуйся вперед, видихаючи. Повертайся повільно.', array['Ривки', 'Тягнеш руками']::text[]),
  ('crunch', 'Скручування на підлозі', 'Crunch', 'abs', '{}'::text[], 'bodyweight', '{}'::text[], 'isolation', 'core', 'core', 'bodyweight', null, null, 1, 'Лежачи, ноги зігнуті. Піднімай лопатки від підлоги, скручуючи корпус, поперек притиснутий.', array['Тягнеш голову руками']::text[])
