-- ЗГЕНЕРОВАНО scripts/build-seed.mjs — не редагуй вручну.
-- Значення КБЖВ на 100 г — орієнтовні, за стандартними рецептурами.

on conflict (id) do update set name_uk = excluded.name_uk, category = excluded.category,
  kcal_100g = excluded.kcal_100g, protein_100g = excluded.protein_100g,
  fat_100g = excluded.fat_100g, carbs_100g = excluded.carbs_100g;

on conflict (id) do update set label_uk = excluded.label_uk, grams = excluded.grams;

-- ───────── Довідники тренувань ─────────
on conflict (id) do update set name_uk = excluded.name_uk, name_en = excluded.name_en, region = excluded.region, group_id = excluded.group_id;

on conflict (id) do update set name_uk = excluded.name_uk, name_en = excluded.name_en;

on conflict (id) do update set name = excluded.name, country = excluded.country;

on conflict (id) do update set name_uk = excluded.name_uk, name_en = excluded.name_en, equipment_type_id = excluded.equipment_type_id, category = excluded.category, weight_step_kg = excluded.weight_step_kg;

on conflict (id) do update set name_uk = excluded.name_uk, name_en = excluded.name_en, primary_muscle_id = excluded.primary_muscle_id, secondary_muscle_ids = excluded.secondary_muscle_ids, equipment_type_id = excluded.equipment_type_id, required_equipment = excluded.required_equipment, mechanics = excluded.mechanics, region = excluded.region, pattern = excluded.pattern, load_type = excluded.load_type, base_lift = excluded.base_lift, base_ratio = excluded.base_ratio, difficulty = excluded.difficulty, technique_uk = excluded.technique_uk, mistakes_uk = excluded.mistakes_uk;

-- Готові профілі залів (owner_id = null — доступні всім для читання)
on conflict (id) do update set name = excluded.name;

delete from gym_equipment where gym_id in ('351b0cc7-1045-5b88-b2a1-8fd3367cfac4', '34272113-906a-5cf0-bc68-ab447d4ccde2', '7373b84c-3895-562d-9b56-71ba85b5c61a', '2f8e32b4-b25b-5298-85ca-5db78de890ee');
